input.code:
const mem = await tools.memory({ command: "view", path: "/memories" }).catch(e => ({ output: String(e) }));

const schema = {
  type: "object",
  properties: {
    verdict: { type: "string" },
    gaps: {
      type: "array",
      items: {
        type: "object",
        properties: {
          issue: { type: "string" },
          section: { type: "string" },
          why: { type: "string" }
        },
        required: ["issue", "section", "why"]
      }
    },
    pointed_section: { type: "string" }
  },
  required: ["verdict", "gaps", "pointed_section"]
};

const draft = String.raw`\section{Setup}
Let $K \subset \mathbb{R}^n$ be compact and $f\colon K \to \mathbb{R}$ continuous.
\section{Main bound}
We claim $\sup_K |f| \le 1$. The proof is omitted.
\section{Discussion}
The bound is sharp for constant functions.`;

// ---- Round 1: Setup only ----
const r1 = await self(
  `You are reviewing a draft paper excerpt. Review ONLY the Setup section. Report whether it is well-posed or has any gap (missing hypotheses, undefined symbols, quantifiers, etc.). Do not analyze other sections; if an issue belongs elsewhere, name its location but do not analyze it.

Draft:
${draft}

Return a structured verdict: "verdict" (one line on Setup), "gaps" (list of issue/section/why), and "pointed_section" (the section the next round should examine — Main bound if Setup names none).`,
  { schema, label: "Round 1: Setup" }
);

const round1 = r1.structured;
if (!round1) throw new Error("Round 1 returned no structured verdict: " + r1.response);

console.log("ROUND 1:", JSON.stringify(round1));

// ---- Gate: wait for reviewer sign-off on round 1's verdict ----
const signoff = await tools.await_signoff({ verdict: `Round 1 (Setup): ${round1.verdict}` });
console.log("SIGNOFF:", signoff.output ?? signoff);

// ---- Round 2: section round 1 points to ----
const target = round1.pointed_section && round1.pointed_section.trim() && round1.pointed_section.trim().toLowerCase() !== "none"
  ? round1.pointed_section.trim()
  : "Main bound";

const r2 = await self(
  `Round 1 reviewed only the Setup section. Round 1's verdict: ${round1.verdict}. Gaps it found: ${JSON.stringify(round1.gaps)}. It points the next round at: "${target}".

Now review ONLY the ${target} section of the draft below. Report whether it is well-posed or has any gap. Do not analyze other sections; if an issue belongs elsewhere, name its location but do not analyze it.

Draft:
${draft}

Return the same schema: "verdict", "gaps", and "pointed_section" (a further section to examine, or "none").`,
  { schema, label: `Round 2: ${target}` }
);

const round2 = r2.structured;
if (!round2) throw new Error("Round 2 returned no structured verdict: " + r2.response);

console.log("ROUND 2:", JSON.stringify(round2));

return {
  memory_listing: mem.output,
  round1,
  signoff: signoff.output ?? null,
  round2,
  pointed_section: target
};

