const schema = {
  type: "object",
  properties: {
    verdict: { type: "string" },
    gaps: {
      type: "array",
      items: {
        type: "object",
        properties: {
          issue: { type: "string" },
          section: { type: "string" },
          why: { type: "string" }
        },
        required: ["issue", "section", "why"]
      }
    },
    pointed_section: { type: "string" }
  },
  required: ["verdict", "gaps", "pointed_section"]
};

const draft = [
  "\\section{Setup}",
  "Let $K \\subset \\mathbb{R}^n$ be compact and $f\\colon K \\to \\mathbb{R}$ continuous.",
  "\\section{Main bound}",
  "We claim $\\sup_K |f| \\le 1$. The proof is omitted.",
  "\\section{Discussion}",
  "The bound is sharp for constant functions."
].join("\n");

try { await tools.memory({ command: "view" }); } catch (e) { /* memory optional here */ }

phase("Round 1: Setup");

const r1 = await self(
  [
    "You are reviewing a draft paper excerpt. Review ONLY the Setup section.",
    "Report whether it is well-posed or has any gap (missing hypotheses, undefined symbols, quantifiers, etc.).",
    "Do not analyze other sections; if an issue belongs elsewhere, name its location but do not analyze it.",
    "Be concise. Do not edit any files; just return the structured verdict.",
    'Set pointed_section to the section the next round should examine ("Main bound" if Setup names none).',
    "",
    "Draft:",
    draft
  ].join("\n"),
  { fork: false, schema, label: "Round 1: Setup" }
);

const round1 = r1.structured;
console.log("R1:", JSON.stringify(round1));

phase("Sign-off");
await await_signoff({ verdict: round1.verdict });

phase("Round 2: " + round1.pointed_section);

const r2 = await self(
  [
    "You are reviewing a draft paper excerpt. You are in round 2 of a review.",
    "Round 1 examined the Setup section and pointed to: " + round1.pointed_section + ".",
    "Review ONLY the " + round1.pointed_section + " section now.",
    "Report whether it is well-posed or has any gap (missing hypotheses, unjustified claims, undefined symbols, quantifiers, etc.).",
    "Do not re-analyze other sections beyond noting where an issue belongs.",
    "Be concise. Do not edit any files; just return the structured verdict.",
    "",
    "Draft:",
    draft
  ].join("\n"),
  { fork: false, schema, label: "Round 2: " + round1.pointed_section }
);

const round2 = r2.structured;
console.log("R2:", JSON.stringify(round2));

return { round1, round2 };
